bool cmp(int a, int b){
    if(tong(a) != tong(b)) return tong(a) < tong(b);  // tieu chi chinh
    return a > b;                                     // tieu chi phu
}

// BAY: neu thieu return o mot nhanh nao do
bool cmp(int a, int b){
    int r1=a%2, r2=b%2;
    if(r1==0 && r2==1) return true;
    if(r1==1 && r2==0) return false;
    if(r1==0 && r2==0) return a > b;
    if(r1==1 && r2==1) return a < b;
    // roi khoi 4 if tren ma khong return -> loi
}

bool cmp(pair<int,int> x, pair<int,int> y){
    if(x.first != y.first) return x.first < y.first;  // hoanh do tang
    return x.second > y.second;                        // tung do giam
}
